// Function signature:
// ssize_t pread64(int fd, void *buf, size_t count, off64_t offset);

int fd = 3; // Target file descriptor
char data_buf[1024];
size_t max_len = sizeof(data_buf);
off64_t target_offset = 0x200000; // 2MB offset
ssize_t bytes_read;

// Reads max_len bytes starting at target_offset.
// Does NOT update the file pointer for fd.
bytes_read = pread64(fd,
                     data_buf,
                     max_len,
                     target_offset);

if (bytes_read == -1) {
    // Error occurred (check errno)
} else if (bytes_read == 0) {
    // EOF reached immediately
}
